import json, sys, numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image
from rcb_client import Robot
S=json.load(open('/app/output/spec.json'))
P=np.array(S['arm']['position_m']); AX=np.array(S['arm']['axis'])
EP=np.array(S['arm']['end_effector']['position_m'])

def fk(q):
    T=np.eye(4)
    for p,a,t in zip(P,AX,q):
        R=Rotation.from_rotvec(a*t).as_matrix(); U=np.eye(4); U[:3,:3]=R; U[:3,3]=p-R@p; T=T@U
    return T

def pose(q):
    T=fk(q); return T[:3,:3]@EP+T[:3,3],T[:3,:3]

def ik(target,q,orient=None):
    def fun(v):
        p,R=pose(v); e=list((p-target)*5)
        if orient is not None: e.extend(Rotation.from_matrix(orient.T@R).as_rotvec())
        e.extend((v-q)*.015)
        return e
    lo=np.array([-20,-2.24,-20,-2.57,-20,-2.09,-20]); hi=np.array([20,2.24,20,2.57,20,2.09,20])
    sol=least_squares(fun,np.clip(q,lo+.001,hi-.001),bounds=(lo,hi),max_nfev=400)
    print('IK',sol.x,'pose',pose(sol.x)[0],'err',np.linalg.norm(fun(sol.x)[:3])); return sol.x

class Control:
    def __init__(self): self.r=Robot(); self.o=self.r.observe(images=False); self.grip=0
    def save(self):
        self.o=self.r.observe();
        for k,v in self.o['images'].items(): Image.fromarray(v).save('/app/output/'+k+'.png')
        np.savez('/app/output/obs.npz',**self.o.get('depth',{})); json.dump({k:v for k,v in self.o.items() if k not in ['images','depth']},open('/app/output/state.json','w'))
        print({k:v for k,v in self.o.items() if k not in ['images','depth']}); print('EE',pose(self.o['proprio']['arm_pos'])[0])
    def move(self,q=None,base=None,grip=None,n=100):
        if grip is not None: self.grip=grip
        for i in range(n):
            a=np.zeros(18); a[10]=self.grip
            if q is not None: a[3:10]=np.clip(np.array(q)-self.o['proprio']['arm_pos'],-.08,.08)
            if base is not None:
                d=np.array(base)-self.o['proprio']['base_pose']; d[:2]*=min(1,.07/(np.linalg.norm(d[:2])+1e-9)); d[2]=np.clip(d[2],-.07,.07); a[:3]=d
            self.o=self.r.step('delta',a.tolist(),images=False)
            if self.o['done']: print('DONE',self.o); break
            eq=q is None or np.max(np.abs(np.array(q)-self.o['proprio']['arm_pos']))<.008
            eb=base is None or np.max(np.abs(np.array(base)-self.o['proprio']['base_pose']))<.003
            if eq and eb and i>=8: break
        print('move steps',i+1)
    def goto(self,p,orient=None,grip=None):
        q=ik(np.array(p),np.array(self.o['proprio']['arm_pos']),orient); self.move(q=q,grip=grip)

if __name__=='__main__':
    c=Control(); cmd=sys.argv[1] if len(sys.argv)>1 else 'observe'
    if cmd=='base': c.move(base=list(map(float,sys.argv[2:5])),grip=float(sys.argv[5]) if len(sys.argv)>5 else 0)
    if cmd=='goto': c.goto(list(map(float,sys.argv[2:5])),Rotation.from_euler('y',np.pi).as_matrix(),grip=float(sys.argv[5]) if len(sys.argv)>5 else 0)
    if cmd=='joint': c.move(q=list(map(float,sys.argv[2:9])),grip=float(sys.argv[9]) if len(sys.argv)>9 else 0)
    c.save()
